using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class MilitaryDebriefTests
{
    static readonly EntityId Lord=new("person:shingen");
    internal static ContractWorld New(){var d=NewGameWorldTests.Setup([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:Lord.Value)]);return NewGameWorld.Create(d.World,d.Registered,"created:test",42,NewGameWorld.CompactPersonalAuthority,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy);}
    static void At(WorldSession s,long t)=>NewGameWorldTests.At(s,t);
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())s.Open(s.PlayerControl,m.Id,s.Revision);}
    static void Send(WorldSession s,NewMilitaryAction a,long amount=0){var i=new NewMilitaryInput(new("request:debrief/"+s.Revision+"/"+a),a,amount);if(a==NewMilitaryAction.Request&&s.DiagnosticSnapshot().NewMilitary!=null)i=i with{CycleContract=NewGameMilitary.RenewalContract};var result=s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);}
    static WorldSession Ready(bool losses=false){var s=new WorldSession(New());Send(s,NewMilitaryAction.Request);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);if(losses){Send(s,NewMilitaryAction.CombatPermit);At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.CombatStart);At(s,s.Seconds+2);Send(s,NewMilitaryAction.CombatEnd);}else At(s,s.Seconds+2);return s;}
    static void Finish(WorldSession s,bool read=true){Send(s,NewMilitaryAction.Recall);var end=s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max();At(s,end+1);Send(s,NewMilitaryAction.Enter);Send(s,NewMilitaryAction.Unload,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);Send(s,NewMilitaryAction.Report);Send(s,NewMilitaryAction.Return);At(s,s.Seconds+3);if(read)Open(s);}
    [Fact]public void UnopenedReturnNoticeHidesDebriefButIssuerHasAcknowledgedReturn(){var s=Ready();Finish(s,false);var w=s.DiagnosticSnapshot();Assert.Empty(NewGameMilitary.Debriefs(w));Assert.Single(NewGameMilitary.Debriefs(w,false));Assert.Single(WorkRelations.Facts(w,Lord,s.PlayerControl));Assert.Empty(WorkRelations.Known(w));}
    [Fact]public void NormalReturnShowsActualReportAndConsumption(){var s=Ready();Finish(s);var w=s.DiagnosticSnapshot();var d=NewGameMilitary.Debriefs(w).Single();Assert.Equal(100,d.Started);Assert.Equal(100,d.Returned);Assert.Equal(0,d.Losses);Assert.Equal(w.NewMilitary!.Uses.Sum(u=>u.Consumed),d.Used);Assert.Contains("布陣",d.Next);Assert.Contains(w.NewMilitary.Reports,p=>p.Message==d.Report&&p.Soldiers==d.Returned);}
    [Fact]public void LossesChangeRecommendationWithoutDeletingOrPunishingPerson(){var s=Ready(true);Finish(s);var w=s.DiagnosticSnapshot();var d=NewGameMilitary.Debriefs(w).Single();Assert.True(d.Losses>0);Assert.Equal(d.Started-d.Returned,d.Losses);Assert.Contains("立て直す",d.Next);Assert.Equal(LifeState.Adult,w.Characters.Single(p=>p.Id==s.PlayerControl).Life);Assert.Equal(Lord,NewGameService.View(w).Principal);Assert.Equal(1000,NewGameWork.Balance(w,s.PlayerControl));}
    [Fact]public void SendingReportWithoutActualReturnDoesNotProduceEvaluation(){var s=Ready();Send(s,NewMilitaryAction.Report);At(s,s.Seconds+3);Open(s);Assert.Empty(NewGameMilitary.Debriefs(s.DiagnosticSnapshot(),false));}
    [Fact]public void ReopeningReturnDoesNotDuplicateSocialFacts(){var s=Ready();Finish(s);var w=s.DiagnosticSnapshot();var d=NewGameMilitary.Debriefs(w).Single();s.Open(s.PlayerControl,d.Notice,s.Revision);Assert.Single(NewGameMilitary.Debriefs(s.DiagnosticSnapshot()));Assert.Single(WorkRelations.Facts(s.DiagnosticSnapshot(),Lord,s.PlayerControl));Assert.Single(WorkRelations.Known(s.DiagnosticSnapshot()).Single().Proofs);}
    [Fact]public void InquiryQuoteCanRecoverDebriefWithoutOpeningOriginal(){var s=Ready();Finish(s,false);Send(s,NewMilitaryAction.Inquire);At(s,s.Seconds+2);var w=s.DiagnosticSnapshot();var quote=w.NewMilitary!.Events.Last(e=>e.Effect==MilitaryEffect.StatusSent);s.Open(s.PlayerControl,new(quote.Message),s.Revision);var d=NewGameMilitary.Debriefs(s.DiagnosticSnapshot()).Single();Assert.Equal(new EntityId(quote.Message),d.Notice);Assert.Single(WorkRelations.Known(s.DiagnosticSnapshot()).Single().Proofs);}
    [Theory][InlineData(false,25000)][InlineData(true,10000)]public void NextCaseUsesKnownPreviousOutcomeForRealPlacement(bool loss,int offset){var s=Ready(loss);Finish(s);var before=NewGameMilitary.TotalStrength(s.DiagnosticSnapshot(),s.Seconds);Send(s,NewMilitaryAction.Request);At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);var w=s.DiagnosticSnapshot();var line=NewGameMilitary.FollowupLine(w);var a=NewGameMilitary.Anchor(w);Assert.Equal(a.X+offset,line[0].X);var input=new NewMilitaryInput(new("request:followup-form"),NewMilitaryAction.Form,A:line[0],B:line[1]);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);Assert.Equal(before,NewGameMilitary.TotalStrength(s.DiagnosticSnapshot(),s.Seconds));Assert.Equal(2,NewGameMilitary.Cases(s.DiagnosticSnapshot()).Length);}
    [Fact]public void CannotRenewUsingUnopenedFeedback(){var s=Ready();Finish(s,false);var i=new NewMilitaryInput(new("request:unread-renew"),NewMilitaryAction.Request){CycleContract=NewGameMilitary.RenewalContract};Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);}
    [Fact]public void RestoredFeedbackAndNextLineAreExact(){var s=Ready(true);Finish(s);Send(s,NewMilitaryAction.Request);s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"debrief-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"manual",w.WorldId,new(0,1));var host=new WorldSessionHost(new(New()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));var x=host.Current.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(NewGameMilitary.Debriefs(w)),ContractJson.Write(NewGameMilitary.Debriefs(x)));Assert.Equal(ContractJson.Write(NewGameMilitary.FollowupLine(w)),ContractJson.Write(NewGameMilitary.FollowupLine(x)));Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(x));}
    [Fact]public void ThirdPartyGetsNoMilitaryTrustFromReturn(){var s=Ready();Finish(s);Assert.Empty(WorkRelations.Facts(s.DiagnosticSnapshot(),new("person:nobunaga"),s.PlayerControl));}
}
